    correctKey: 'A',
    explanation: '設備の配置計画は、施工のしやすさだけでなく、竣工後の点検・保守・更新のしやすさ（保全性）を考慮して検討しなければならない。機器の周囲には点検通路と部品交換のスペース、冷凍機ではチューブ引抜きスペースが必要であり、フィルタ、弁、ダンパ、掃除口には手が届く位置と点検口を計画する。さらに機器の耐用年数はおおむね15〜20年で必ず更新の時期が来るため、搬出入経路と開口も確保しておく。したがって施工のしやすさのみを優先すればよいという記述は誤りである。\n\n【図解】保全性への配慮\n　配慮事項｜内容｜考慮しない場合\n　点検スペース｜機器周囲の通路と作業空間｜日常点検ができない\n　点検口｜ダンパや弁、掃除口の位置に設ける｜天井を解体する必要が生じる\n　更新経路｜機器の搬出入経路と開口｜更新時に大規模な解体が必要\n　⇒ 建物の寿命に対し機器の寿命は短く、必ず更新の時期が来る\n　⚠ 「施工性のみ優先」は誤り。チューブ引抜きスペースの失念が典型的失敗。',
